        const header = Buffer.alloc(8);
        header.write(chunk.fourCC, 0, 'ascii');
        header.writeUInt32LE(chunk.data.length, 4);
        return chunk.data.length % 2 ? [header, chunk.data, Buffer.alloc(1)] : [header, chunk.data];
